    public static bool TestFilteredCatchCode(byte[]? bytes, int part)
    {
        if ((uint)part >= (uint)FilteredCatchShapes.Length || bytes is null)
            return false;
        var shape = FilteredCatchShapes[part];
        if (bytes.Length != shape.Hex.Length / 2)
            return false;
        byte[] normalized = [..bytes];
        foreach (var field in shape.Fields)
            normalized.AsSpan(field.Field, 4).Clear();
        return normalized.AsSpan().SequenceEqual(Convert.FromHexString(shape.Hex));
    }

    public static bool TestFilteredCatchOffsets(byte[]? code, uint returnOffset, uint continuationOffset)
    {
        if (code is null || code.Length != 295 || returnOffset != 36 || continuationOffset != returnOffset + 1 || code[31] != 0xE8 || code[returnOffset] != 0x90 || !code.AsSpan((int)continuationOffset, 4).SequenceEqual(new byte[] { 0x48, 0x8B, 0x4D, 0x10 }))
            return false;
        foreach (int end in new[]
        {
            178,
            295
        }

        )
        {
            int lea = end - 12, field = lea + 3;
            if (!code.AsSpan(lea, 3).SequenceEqual(new byte[] { 0x48, 0x8D, 0x05 }) || !code.AsSpan(end - 5, 5).SequenceEqual(new byte[] { 0x48, 0x83, 0xC4, 0x28, 0xC3 }) || (long)field + 4 + BinaryPrimitives.ReadInt32LittleEndian(code.AsSpan(field, 4)) != continuationOffset)
                return false;
        }

        return true;
    }

    public static bool TestFilteredCatchEhTable(byte[]? bytes) => bytes is { Length: 11 } && bytes.AsSpan().SequenceEqual(new byte[] { 4, 62, 52, 254, 120, 62, 52, 213, 3, 201, 2 });
    public static bool TestFilteredCatchUnwind(byte[]? bytes, int part, ulong table)
    {
        byte[] prefix = part switch
        {
            0 => [1, 4, 1, 0, 4, 66, 0],
            1 => [1, 5, 2, 0, 5, 114, 1, 80, 4],
            2 => [1, 4, 1, 0, 4, 66, 2],
            3 => [1, 4, 1, 0, 4, 66, 1],
            _ => []
        };
        return prefix.Length != 0 && bytes is not null && bytes.Length == prefix.Length + (part == 1 ? 4 : 0) && bytes.AsSpan(0, prefix.Length).SequenceEqual(prefix) && (part != 1 || table is> 0 and <= uint.MaxValue && BinaryPrimitives.ReadUInt32LittleEndian(bytes.AsSpan(prefix.Length)) == table);
    }
